import java.lang.reflect.*;

interface Biz { void a(); void b(); }
class BizImpl implements Biz {
    public void a() { System.out.println("  [a] call b() internally"); b(); }
    public void b() { System.out.println("  [b] business logic"); }
}
class H implements InvocationHandler {
    Object target;
    H(Object t) { target = t; }
    public Object invoke(Object p, Method m, Object[] args) throws Throwable {
        System.out.println("[advice] before " + m.getName());
        Object r = m.invoke(target, args);
        System.out.println("[advice] after " + m.getName());
        return r;
    }
}
public class Main {
    public static void main(String[] a) throws Exception {
        Biz proxy = (Biz) Proxy.newProxyInstance(Biz.class.getClassLoader(),
            new Class[]{Biz.class}, new H(new BizImpl()));
        System.out.println("--- external call to a() ---");
        proxy.a();
        System.out.println("--- external call to b() ---");
        proxy.b();
    }
}
